contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Run with arbitrary amount of wei sent from the caller to this test contract,
    // then forwarded to c via c.go{value: amount}().
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        // record balance of c before
        uint256 balBefore = address(c).balance;

        // Call go sending `amount` wei to c. Capture whether it reverted.
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call: owner's address must be unchanged, and if the call did not revert,
        // c's balance should be zero (it forwards remaining balance to owner).
        // If the call reverted, state must be unchanged: owner stays the same and balance equals before.
        assert(
            (reverted && c.owner() == ownerBefore && address(c).balance == balBefore)
            || (!reverted && c.owner() == ownerBefore && address(c).balance == 0)
        );
    }

    receive() external payable {}
}

